package com.sjd.scan;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.ColorStateList;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.concurrent.*;
public class ManualEditor extends Dialog {
 public interface Apply {void accept(int[] values);}
 final Bitmap base;Bitmap rendered;final int[] values;final Apply apply;final ExecutorService executor=Executors.newSingleThreadExecutor();final Handler handler=new Handler(Looper.getMainLooper());volatile int generation=0;volatile boolean closed=false;ImageView image;TextView status;SeekBar[] sliders=new SeekBar[6];TextView[] labels=new TextView[6];final int[] mins={-60,-50,0,0,0,0},maxs={60,80,150,100,100,100};final String[] names={"روشنایی","کنتراست","رنگ (صفر = خاکستری)","وضوح لبه‌ها","کاهش سایهٔ چروک کاغذ","نرم‌کردن نویز"};boolean resetting=false;
 public ManualEditor(Context c,Bitmap input,int[] current,Apply callback){super(c,android.R.style.Theme_Material_NoActionBar);values=current.clone();apply=callback;float sc=Math.min(1,1000f/Math.max(input.getWidth(),input.getHeight()));base=Bitmap.createScaledBitmap(input,Math.max(1,(int)(input.getWidth()*sc)),Math.max(1,(int)(input.getHeight()*sc)),true);}
 int dp(int n){return (int)(n*getContext().getResources().getDisplayMetrics().density+.5f);}
 TextView text(String s,int size){TextView t=new TextView(getContext());t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER);t.setPadding(0,dp(4),0,dp(4));return t;}
 Button button(String s){Button b=new Button(getContext());b.setText(s);b.setTextSize(13);b.setTextColor(Color.WHITE);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(2),0,dp(2),0);b.setBackgroundTintList(ColorStateList.valueOf(0xff244158));return b;}
 protected void onCreate(Bundle saved){super.onCreate(saved);LinearLayout root=new LinearLayout(getContext());root.setOrientation(1);root.setBackgroundColor(0xff102438);root.setPadding(dp(12),dp(8),dp(12),dp(8));root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(dp(12)+in.getSystemWindowInsetLeft(),dp(8)+in.getSystemWindowInsetTop(),dp(12)+in.getSystemWindowInsetRight(),dp(8)+in.getSystemWindowInsetBottom());return in;});root.addView(text("تنظیم دستی تصویر",21));image=new ImageView(getContext());image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setImageBitmap(base);root.addView(image,new LinearLayout.LayoutParams(-1,0,1));status=text("پیش‌نمایش • خروجی با کیفیت کامل ذخیره می‌شود",12);root.addView(status);ScrollView scroll=new ScrollView(getContext());LinearLayout settings=new LinearLayout(getContext());settings.setOrientation(1);scroll.addView(settings);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));for(int i=0;i<6;i++){final int k=i;labels[i]=text(names[i]+" : "+values[i],14);settings.addView(labels[i]);SeekBar s=new SeekBar(getContext());sliders[i]=s;s.setMax(maxs[i]-mins[i]);s.setProgress(values[i]-mins[i]);s.setProgressTintList(ColorStateList.valueOf(0xff28d9bd));s.setThumbTintList(ColorStateList.valueOf(0xff28d9bd));settings.addView(s,new LinearLayout.LayoutParams(-1,dp(34)));s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){queue();}public void onProgressChanged(SeekBar b,int v,boolean user){values[k]=v+mins[k];labels[k].setText(names[k]+" : "+values[k]);if(user&&!resetting)queue();}});}
 LinearLayout row=new LinearLayout(getContext());root.addView(row);Button cancel=button("انصراف"),reset=button("بازنشانی"),compare=button("قبل / بعد"),ok=button("اعمال");for(Button b:new Button[]{cancel,reset,compare,ok})row.addView(b,new LinearLayout.LayoutParams(0,dp(52),1));cancel.setOnClickListener(v->dismiss());reset.setOnClickListener(v->{resetting=true;for(int i=0;i<6;i++)sliders[i].setProgress((i==2?100:0)-mins[i]);resetting=false;queue();});compare.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){image.setImageBitmap(base);return true;}if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL){image.setImageBitmap(rendered==null?base:rendered);return true;}return true;});ok.setOnClickListener(v->{int[] copy=values.clone();dismiss();apply.accept(copy);});setContentView(root);queue();}
 void queue(){final int id=++generation;final int[] copy=values.clone();status.setText("در حال به‌روزرسانی پیش‌نمایش…");handler.postDelayed(()->{if(closed||id!=generation)return;executor.execute(()->{if(closed||id!=generation)return;try{Bitmap b=Processor.enhance(base,copy);handler.post(()->{if(closed||id!=generation){b.recycle();return;}Bitmap old=rendered;rendered=b;image.setImageBitmap(b);if(old!=null&&old!=base)old.recycle();status.setText("برای مقایسه، «قبل / بعد» را نگه دارید");});}catch(Throwable e){handler.post(()->{if(!closed)status.setText("پیش‌نمایش انجام نشد؛ شدت تنظیمات را کمتر کنید");});}});},150);}
 public void dismiss(){closed=true;generation++;handler.removeCallbacksAndMessages(null);executor.shutdown();super.dismiss();}
}
